  vec3f(-2.26070, 0.92948, -0.23992),
  vec3f(-3.55958, 0.92947, -0.24014),
  vec3f(3.58933, 0.87768, -0.65803),
  vec3f(2.22999, 0.86607, -0.69889),
  vec3f(-0.87073, 0.69717, -7.49343),
  vec3f(-1.96932, 0.69690, -7.49342),
  vec3f(3.06812, 1.02740, -7.49321),
  vec3f(1.40403, 1.02644, -7.49382));
const L_DIR = array<vec3f, 10>(
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820));
const L_COLOR = array<vec3f, 10>(
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000));
const L_SHAPE = array<vec4f, 10>(
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0));
