      let c = max(textureSampleLevel(inputTexture, inputSampler, at + o * side, 0.0).rgb, vec3f(0.0));
      share = share + clamp(max(c.r, max(c.g, c.b)) / max(params.sourceLevel, 1e-4), 0.0, 1.0);
    }
