  let a = 0.5 + 0.5 * sin(x * 6.2831853 + sin(x * 0.37) * 3.0);
  let b = 0.5 + 0.5 * sin(x * 2.618 * 6.2831853 + 1.3);
  return pow(a * 0.6 + b * 0.4, 1.6);
}

