  for (var k = 0; k < TAPS; k = k + 1) {
    let w = exp(-f32(k) / (f32(TAPS) * params.decay));
    // Upward column: gather from BELOW (texture y grows downward).
    let at = uv + vec2f(0.0, f32(k) * params.step);
