const BONES: u32 = 19u;
const BONE_PARENT = array<i32, 19>(-1, 0, 1, 2, 3, 2, 5, 6, 7, 2, 9, 10, 11, 0, 13, 14, 0, 16, 17);
const BONE_HEAD = array<vec3f, 19>(vec3f(0.00000, 0.96179, 0.00482), vec3f(0.00000, 1.05056, -0.02764), vec3f(0.00000, 1.18620, -0.02634), vec3f(0.00000, 1.53777, 0.01311), vec3f(0.00000, 1.63664, 0.04730), vec3f(0.02343, 1.46157, 0.02581), vec3f(0.19063, 1.43167, 0.01959), vec3f(0.36319, 1.23385, 0.01839), vec3f(0.50031, 1.10285, 0.21346), vec3f(-0.02343, 1.46157, 0.02581), vec3f(-0.19063, 1.43167, 0.01959), vec3f(-0.36319, 1.23385, 0.01839), vec3f(-0.50031, 1.10285, 0.21346), vec3f(0.11126, 0.95615, -0.00587), vec3f(0.15488, 0.51706, 0.02909), vec3f(0.20151, 0.07392, 0.01538), vec3f(-0.11126, 0.95615, -0.00587), vec3f(-0.15488, 0.51706, 0.02909), vec3f(-0.20151, 0.07392, 0.01538));

fn boneAngles(i: u32, ctx: PointCtx) -> vec3f {
  switch i {
    case 0u: { return ctx.params.pelvis; }
    case 1u: { return ctx.params.spine; }
    case 2u: { return ctx.params.chest; }
    case 3u: { return ctx.params.neck; }
    case 4u: { return ctx.params.head; }
    case 5u: { return ctx.params.shoulderL; }
    case 6u: { return ctx.params.upperarmL; }
    case 7u: { return ctx.params.forearmL; }
    case 8u: { return ctx.params.handL; }
    case 9u: { return ctx.params.shoulderR; }
    case 10u: { return ctx.params.upperarmR; }
    case 11u: { return ctx.params.forearmR; }
    case 12u: { return ctx.params.handR; }
    case 13u: { return ctx.params.thighL; }
    case 14u: { return ctx.params.shinL; }
    case 15u: { return ctx.params.footL; }
    case 16u: { return ctx.params.thighR; }
    case 17u: { return ctx.params.shinR; }
    case 18u: { return ctx.params.footR; }
    default: { return vec3f(0.0); }
  }
}

fn euler(e: vec3f) -> mat3x3f {
  let cx = cos(e.x); let sx = sin(e.x);
  let cy = cos(e.y); let sy = sin(e.y);
  let cz = cos(e.z); let sz = sin(e.z);
  let rx = mat3x3f(vec3f(1.0, 0.0, 0.0), vec3f(0.0, cx, sx), vec3f(0.0, -sx, cx));
  let ry = mat3x3f(vec3f(cy, 0.0, -sy), vec3f(0.0, 1.0, 0.0), vec3f(sy, 0.0, cy));
  let rz = mat3x3f(vec3f(cz, sz, 0.0), vec3f(-sz, cz, 0.0), vec3f(0.0, 0.0, 1.0));
  return rz * ry * rx;
}

struct Xf {
  m: mat3x3f,
  t: vec3f,
};

// The bone's world transform: its own rotation about its head, then each ancestor's.
fn boneXf(bone: u32, ctx: PointCtx) -> Xf {
  var acc: Xf;
  acc.m = mat3x3f(vec3f(1.0, 0.0, 0.0), vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0));
  acc.t = vec3f(0.0);
  var j = i32(bone);
  for (var level = 0u; level < 8u; level = level + 1u) {
    if (j < 0 || u32(j) >= BONES) { break; }
    let r = euler(boneAngles(u32(j), ctx));
    let h = BONE_HEAD[u32(j)];
    acc.m = r * acc.m;
    acc.t = r * (acc.t - h) + h;
    j = BONE_PARENT[u32(j)];
  }
  return acc;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  // Linear-blend skinning over the four influences the decoder normalised to sum 1.
  var posed = vec3f(0.0);
  var bent = vec3f(0.0);
  var total = 0.0;
  for (var k = 0u; k < 4u; k = k + 1u) {
    let w = p.weights[k];
    if (w <= 0.0) { continue; }
    let x = boneXf(min(u32(p.joints[k] + 0.5), BONES - 1u), ctx);
    posed = posed + w * (x.m * p.position + x.t);
    bent = bent + w * (x.m * p.normal);
    total = total + w;
  }
  if (total <= 0.0) {
    // Nothing skins this vertex: it keeps its rest place.
    posed = p.position;
    bent = p.normal;
  } else {
    posed = posed / total;
  }
  let normal = normalize(bent);
  let c = cos(ctx.params.yaw);
  let s = sin(ctx.params.yaw);
  let turn = mat3x3f(vec3f(c, 0.0, -s), vec3f(0.0, 1.0, 0.0), vec3f(s, 0.0, c));
  q.position = ctx.params.place + turn * posed;
  q.normal = turn * normal;
  return q;
}

